"""
    Lithostatic stress according to Pylith's definition of g=9.80665
    """
def calc_lithostat(z: Any, p: Any = 2700.0, g: Any = 9.80665) -> object {
    litho = p * g * z;
    print(('%.3e' % litho));
    return litho;
}

test_blocks:
test "t0" {
    assert (calc_lithostat(1.0, 2700.0, 9.80665) == calc_lithostat(1.0));;
}

test "t1" {
    assert (calc_lithostat(3, 2700.0, 9.80665) == (2700 * 9.80665 * 3));;
}

test "t2" {
    assert (calc_lithostat(0) == 0);;
}

test "t3" {
    assert (calc_lithostat(3, 9.80665, 2700) == (2700 * 9.80665 * 3));;
}

test "t4" {
    assert (calc_lithostat(0) == 0.0);;
}

test "t5" {
    assert (calc_lithostat(2.0, 2700.0, 9.80665) == calc_lithostat(2.0));;
}

test "t6" {
    assert (calc_lithostat(0.0) == 0.0);;
}

test "t7" {
    assert (calc_lithostat(3, 2700, 9.80665) == (2700 * 9.80665 * 3));;
}

test "t8" {
    assert (calc_lithostat(3) == (2700 * 9.80665 * 3));;
}

test "t9" {
    assert (calc_lithostat(1.0) == (2700.0 * 9.80665));;
}
